import React from "react";
import { motion } from "framer-motion";
import { useNavigate } from "react-router-dom";
import PageWrapper from "../components/PageWrapper";

const Login = () => {
  const navigate = useNavigate();

  return (
    <PageWrapper>
      <div className="flex items-center justify-center min-h-[80vh] bg-gradient-to-tr from-indigo-100 to-blue-100 px-6">
        <motion.div
          initial={{ scale: 0.8, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          transition={{ duration: 0.6 }}
          className="bg-white/80 backdrop-blur-lg shadow-2xl rounded-2xl p-10 w-full max-w-md text-center"
        >
          <h1 className="text-3xl font-bold text-blue-700 mb-6">Welcome Back</h1>
          <input
            type="email"
            placeholder="Email"
            className="w-full p-3 mb-3 border rounded-md"
          />
          <input
            type="password"
            placeholder="Password"
            className="w-full p-3 mb-6 border rounded-md"
          />
          <motion.button
            whileTap={{ scale: 0.95 }}
            onClick={() => navigate("/home")}
            className="bg-blue-600 text-white px-6 py-3 rounded-md hover:bg-blue-700 transition"
          >
            Sign In
          </motion.button>
          <p className="text-gray-500 mt-4 text-sm">
            Don’t have an account?{" "}
            <span
              onClick={() => navigate("/signup")}
              className="text-blue-600 cursor-pointer hover:underline"
            >
              Sign Up
            </span>
          </p>
        </motion.div>
      </div>
    </PageWrapper>
  );
};

export default Login;
